Q: JSF commandbutton not being called when adding primefaces ajax A: <pre><code>import net.minidev.json.JSONArray;
import net.minidev.json.JSONObject;

import java.io.IOException;
import java.text.Normalizer;
import java.util.Locale;
import java.util.Map;

public class TestIndemnisationEligibilite {

    public static synchronized boolean comparisonJava(Map&lt;String, Object&gt; param) throws IOException {

        // ------------------ Read inputs from Karate ------------------
        @SuppressWarnings(&quot;unchecked&quot;)
        Map&lt;String, Object&gt; response = (Map&lt;String, Object&gt;) param.get(&quot;response&quot;);

        @SuppressWarnings(&quot;unchecked&quot;)
        Map&lt;String, Object&gt; expected = (Map&lt;String, Object&gt;) param.get(&quot;expected&quot;);

        if (response == null) {
            throw new IllegalArgumentException(&quot;param['response'] is null&quot;);
        }
        if (expected == null) {
            throw new IllegalArgumentException(&quot;param['expected'] is null&quot;);
        }

        // eligibilityResponse key can be written with typo in some payloads
        @SuppressWarnings(&quot;unchecked&quot;)
        Map&lt;String, Object&gt; actualEligibility =
                (Map&lt;String, Object&gt;) firstNonNull(response, &quot;eligibilityResponse&quot;, &quot;eligibilityReponse&quot;);

        if (actualEligibility == null) {
            throw new IllegalArgumentException(
                    &quot;response['eligibilityResponse'/'eligibilityReponse'] is null. Available keys: &quot; + response.keySet()
            );
        }

        @SuppressWarnings(&quot;unchecked&quot;)
        Map&lt;String, Object&gt; expectedEligibility =
                (Map&lt;String, Object&gt;) firstNonNull(expected, &quot;eligibilityResponse&quot;, &quot;eligibilityReponse&quot;);

        if (expectedEligibility == null) {
            throw new IllegalArgumentException(
                    &quot;expected['eligibilityResponse'/'eligibilityReponse'] is null. Available keys: &quot; + expected.keySet()
            );
        }

        // ------------------ Extract rules array ------------------
        Object rulesObj = actualEligibility.get(&quot;nonEligibleRules&quot;);
        if (!(rulesObj instanceof JSONArray)) {
            throw new IllegalArgumentException(
                    &quot;actualEligibility['nonEligibleRules'] is not JSONArray. It is: &quot; +
                            (rulesObj == null ? &quot;null&quot; : rulesObj.getClass().getName())
            );
        }
        JSONArray nonEligibleRules = (JSONArray) rulesObj;

        // ------------------ Debug prints ------------------
        System.out.println(&quot;The response is below:&quot;);
        System.out.println(nonEligibleRules);

        System.out.println(&quot;THE EXPECTED IS BELOW:&quot;);
        System.out.println(expectedEligibility);

        System.out.println(&quot;Expected class: &quot; + expectedEligibility.getClass().getName());
        System.out.println(&quot;Rules class: &quot; + nonEligibleRules.getClass().getName());

        // ------------------ Matching logic ------------------
        // must match BOTH: reason and clientReason
        // ignore French accents + handle � encoding
        // response may contain multiple rules -&gt; pass if at least ONE matches

        String expectedReason = norm(asString(expectedEligibility.get(&quot;reason&quot;)));
        String expectedClientReason = norm(asString(expectedEligibility.get(&quot;clientReason&quot;)));

        // Template support: [nom commercial] [convention] =&gt; wildcard
        String expectedClientReasonRegex = toTemplateRegex(expectedClientReason);

        for (Object item : nonEligibleRules) {

            String actualReason;
            String actualClientReason;

            // Karate arrays often contain LinkedHashMap, not JSONObject
            if (item instanceof JSONObject obj) {
                actualReason = norm(asString(obj.get(&quot;reason&quot;)));
                actualClientReason = norm(asString(obj.get(&quot;clientReason&quot;)));
            } else if (item instanceof Map) {
                @SuppressWarnings(&quot;unchecked&quot;)
                Map&lt;String, Object&gt; obj = (Map&lt;String, Object&gt;) item;
                actualReason = norm(asString(obj.get(&quot;reason&quot;)));
                actualClientReason = norm(asString(obj.get(&quot;clientReason&quot;)));
            } else {
                continue;
            }

            boolean reasonMatches = actualReason.equals(expectedReason);

            boolean clientReasonMatches;
            if (expectedClientReason.contains(&quot;[&quot;) &amp;&amp; expectedClientReason.contains(&quot;]&quot;)) {
                clientReasonMatches = actualClientReason.matches(expectedClientReasonRegex);
            } else {
                // tolerant: expected may be shorter/longer than actual
                clientReasonMatches =
                        actualClientReason.contains(expectedClientReason) ||
                        expectedClientReason.contains(actualClientReason);
            }

            if (reasonMatches &amp;&amp; clientReasonMatches) {
                return true;
            }
        }

        return false;
    }

    // ------------------ Helpers ------------------

    private static Object firstNonNull(Map&lt;String, Object&gt; map, String... keys) {
        for (String k : keys) {
            Object v = map.get(k);
            if (v != null) return v;
        }
        return null;
    }

    private static String asString(Object v) {
        return v == null ? &quot;&quot; : String.valueOf(v);
    }

    /**
     * Normalize strings to compare French text safely:
     * - lowercase
     * - remove accents (é -&gt; e)
     * - normalize apostrophes
     * - remove encoding replacement char '�'
     * - collapse spaces
     */
    private static String norm(String s) {
        if (s == null) return &quot;&quot;;

        String x = s;

        x = x.replace('’', '\'')
             .replace('‘', '\'')
             .replace('´', '\'')
             .replace('`', '\'');

        x = x.toLowerCase(Locale.ROOT);

        x = Normalizer.normalize(x, Normalizer.Form.NFD)
                .replaceAll(&quot;\\p{M}+&quot;, &quot;&quot;);

        // remove bad encoding replacement char(s)
        x = x.replace(&quot;\uFFFD&quot;, &quot;&quot;);
        x = x.replace(&quot;�&quot;, &quot;&quot;);

        x = x.replaceAll(&quot;\\s+&quot;, &quot; &quot;).trim();

        return x;
    }

    /**
     * Converts placeholders like [nom commercial] or [convention] into regex wildcards.
     * The expected string should already be normalized with norm().
     */
    private static String toTemplateRegex(String expectedNorm) {

        // escape regex chars
        String escaped = expectedNorm
                .replace(&quot;\\&quot;, &quot;\\\\&quot;)
                .replace(&quot;.&quot;, &quot;\\.&quot;)
                .replace(&quot;?&quot;, &quot;\\?&quot;)
                .replace(&quot;+&quot;, &quot;\\+&quot;)
                .replace(&quot;*&quot;, &quot;\\*&quot;)
                .replace(&quot;^&quot;, &quot;\\^&quot;)
                .replace(&quot;$&quot;, &quot;\\$&quot;)
                .replace(&quot;{&quot;, &quot;\\{&quot;)
                .replace(&quot;}&quot;, &quot;\\}&quot;)
                .replace(&quot;(&quot;, &quot;\\(&quot;)
                .replace(&quot;)&quot;, &quot;\\)&quot;)
                .replace(&quot;|&quot;, &quot;\\|&quot;);

        // [anything] =&gt; .*
        String withWildcards = escaped.replaceAll(&quot;\\\\[.*?\\\\]&quot;, &quot;.*&quot;);

        return &quot;.*&quot; + withWildcards + &quot;.*&quot;;
    }
}
</code></pre>

Q: jQuery Ajax POST operation doesn&#39;t pass data A: <p>The data type you are passing <code>data:{thirdclass:&quot;thirdclass&quot;}</code> is text not <strong>JSON</strong>. Use dataType:&quot;text&quot;</p>
<pre><code>$.ajax({
type: &quot;POST&quot;,
url: &quot;results_thirdclass_trialgp.php&quot;,
data: { thirdclass: &quot;thirdclass&quot; },
dataType: &quot;text&quot;,
success: function (result) {
   $(&quot;.third&quot;).html(result);
   console.log(result); 
}
});
</code></pre>
<p>or send data in propper JSON format:</p>
<pre><code>$.ajax({
type: &quot;POST&quot;,
url: &quot;results_thirdclass_trialgp.php&quot;,
data: JSON.stringify({ thirdclass: &quot;thirdclass&quot; }),
contentType: &quot;application/json; charset=utf-8&quot;,
dataType: &quot;text&quot;,
success: function (result) {
   $(&quot;.third&quot;).html(result);
   console.log(result);
 }
});
</code></pre>
